input.content:
workspace "Sistema de Agendamento" "Agendamento de compromissos com lembretes por SMS." {

    !identifiers hierarchical

    model {
        cliente = person "Cliente" "Pessoa que consulta e gerencia seus agendamentos."
        atendente = person "Atendente" "Pessoa da equipe que gerencia agendamentos pelo painel web."

        agendamento = softwareSystem "Sistema de Agendamento" "Permite criar e gerenciar agendamentos e envia lembretes por SMS." {
            app = container "App Mobile" "Permite ao cliente gerenciar seus agendamentos pelo celular." "Flutter" "Mobile App"
            painel = container "Painel Web" "Permite gerenciar agendamentos pelo navegador." "Vue" "Web Browser"
            api = container "API" "Expõe as operações de agendamento e dispara os lembretes." "Python, FastAPI"
            db = container "Banco de Dados" "Guarda os agendamentos." "PostgreSQL 15" "Database"
        }

        twilio = softwareSystem "Twilio" "Serviço de envio de SMS." "External"

        cliente -> agendamento.app "Gerencia agendamentos usando"
        atendente -> agendamento.painel "Gerencia agendamentos usando"

        agendamento.app -> agendamento.api "Faz requisições para"
        agendamento.painel -> agendamento.api "Faz requisições para"
        agendamento.api -> agendamento.db "Lê e grava agendamentos em"
        agendamento.api -> twilio "Envia lembretes por SMS via"
        twilio -> cliente "Entrega lembretes por SMS para"
    }

    views {
        systemContext agendamento "SystemContext" {
            include *
            autoLayout
        }

        container agendamento "Containers" {
            include *
            autoLayout
        }

        styles {
            element "Person" {
                shape person
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Database" {
                shape cylinder
            }
            element "Mobile App" {
                shape mobileDeviceLandscape
            }
            element "Web Browser" {
                shape webBrowser
            }
        }

        theme default
    }

    configuration {
        scope softwaresystem
    }

}

